require_relative "ref/liquid"

def liquid_render(t, assigns = {}) = Liquid::Template.parse(t).render(assigns)

def show(label, t, assigns = {})
  puts("#{label}: #{liquid_render(t, assigns).inspect}")
rescue Liquid::SyntaxError => e
  puts("#{label}: Liquid::SyntaxError: #{e.message}")
rescue ZeroDivisionError => e
  puts("#{label}: ZeroDivisionError: #{e.message}")
end

puts("== output")
ctx = {"name" => "World", "n" => 3, "f" => 2.5, "t" => true, "nope" => nil, "s" => "a <b> & 'c'",
           "xs" => [3, 1, 2], "h" => {"k" => "v", "size" => 99, "n" => {"m" => "deep"}},
           "words" => ["alpha", "beta", "gamma"], "empty_s" => "", "empty_a" => [], "blank_s" => "  "}
show("var", "Hello {{ name }}! {{n}} {{ f }} {{ t }} [{{ nope }}] [{{ missing }}]", ctx)
show("literals", "{{ 'sq' }} {{ \"dq\" }} {{ 42 }} {{ -1.5 }} {{ true }} {{ nil }} {{ (1..4) }}", ctx)
show("lookups", "{{ h.k }} {{ h['k'] }} {{ h[\"n\"].m }} {{ h.n.m }} {{ h.size }} {{ xs[0] }} {{ xs[-1] }} {{ xs.size }} {{ xs.first }} {{ xs.last }} {{ name.size }} {{ words[n] }} {{ h.missing.x }}", ctx)
show("array output", "{{ xs }} {{ words }} {{ h }}", ctx)
show("whitespace", "a {{- name -}} b\n{%- if t -%}\n  yes\n{%- endif -%}\nc", ctx)
show("unterminated", "{{ name", ctx)

