show("truncate", "{{ 'Ground control to Major Tom.' | truncate: 20 }} {{ 'Ground control to Major Tom.' | truncate: 25, ', and so on' }} {{ 'Ground control' | truncate: 20 }} {{ 'abcdef' | truncate: 2 }} {{ 'Ground control to Major Tom.' | truncatewords: 3 }} {{ 'a b' | truncatewords: 3 }}", ctx)
show("escape", "{{ s | escape }} [{{ nope | escape }}] {{ s }}", ctx)
