show("date", "{{ 1234567890 | date: '%Y-%m-%d' }} {{ '2026-10-09 15:04:05' | date: '%d %b %Y %H:%M' }} {{ '2026-10-09' | date: '%A' }} {{ 'not a date' | date: '%Y' }} {{ nope | date: '%Y' }} {{ 'x' | date: '' }}", ctx)
show("date Time", "{{ when | date: '%Y/%m/%d %H:%M:%S' }}", {"when" => Time.new(2026, 1, 2, 3, 4, 5, "+00:00")})
