show("empty blank", "{% if empty_s == empty %}1{% endif %}{% if empty_a == empty %}2{% endif %}{% if name == empty %}3{% endif %}{% if blank_s == blank %}4{% endif %}{% if nope == blank %}5{% endif %}{% if n == blank %}6{% endif %}{% if xs != empty %}7{% endif %}", ctx)
