show("limit offset reversed", "{% for x in xs limit: 2 %}{{ x }}{% endfor %}|{% for x in xs offset: 1 %}{{ x }}{% endfor %}|{% for x in xs reversed %}{{ x }}{% endfor %}|{% for x in xs offset: 1 limit: 1 reversed %}{{ x }}{% endfor %}", ctx)
