puts("== parse twice")
tmpl = Liquid::Template.parse("{{ greeting | default: 'Hello' }}, {{ who }}!{% for i in (1..2) %} {{ i }}{% endfor %}")
puts(tmpl.render({"who" => "A"}))
puts(tmpl.render({"who" => "B", "greeting" => "Yo"}))
puts(tmpl.render)
